function validate(input) {
  const [nums, rowsCount, colsCount] = input;
  if (!Array.isArray(nums) || nums.length > 250) return 'nums has at most 250 elements.';
  if (!nums.every(value => Number.isInteger(value) && value >= 1 && value <= 1000)) return 'Every element of nums is an integer from 1 to 1000.';
  if (!Number.isInteger(rowsCount) || rowsCount < 1 || rowsCount > 250) return 'rowsCount must be an integer from 1 to 250.';
  if (!Number.isInteger(colsCount) || colsCount < 1 || colsCount > 250) return 'colsCount must be an integer from 1 to 250.';
  return null;
}

