function adapt(input, solve, kit) {
  const [nums, rowsCount, colsCount] = input;
  if (typeof nums.snail !== 'function') throw new Error('Arrays have no snail method yet: assign a function to Array.prototype.snail.');
  const matrix = nums.snail(rowsCount, colsCount);
  if (!Array.isArray(matrix)) throw new Error('snail must return an array: the grid as a list of rows, or [] when the sizes do not fit.');
  kit.trace(`nums.snail(${rowsCount}, ${colsCount}) returns ${matrix.length} rows`);
  return matrix;
}

