Array.prototype.snail = function (rowsCount, colsCount) {
  if (this.length !== rowsCount * colsCount) return [];
  // Build the grid row by row, computing which element of the array lands in each cell.
  const grid = [];
  for (let r = 0; r < rowsCount; r++) {
    const line = [];
    for (let c = 0; c < colsCount; c++) {
      // Column c holds the block starting at c * rowsCount, read downward when c is even and upward when it is odd.
      const offset = c % 2 === 0 ? r : rowsCount - 1 - r;
      line.push(this[c * rowsCount + offset]);
    }
    grid.push(line);
  }
  return grid;
};

