function generate(rand, size) {
  let rowsCount, colsCount;
  if (size === 'small') {
    rowsCount = 1 + Math.floor(rand() * 5);
    colsCount = 1 + Math.floor(rand() * 5);
  } else {
    // Pick a length near the limit and one of its divisors as the number of rows.
    const total = 200 + Math.floor(rand() * 51), divisors = [];
    for (let d = 1; d <= total; d++) if (total % d === 0) divisors.push(d);
    rowsCount = divisors[Math.floor(rand() * divisors.length)];
    colsCount = total / rowsCount;
  }
  let length = rowsCount * colsCount;
  // Sometimes the sizes do not fit, and the answer is [].
  if (rand() < (size === 'small' ? 0.25 : 0.1)) length += (rand() < 0.5 ? -1 : 1) * (1 + Math.floor(rand() * 3));
  length = Math.max(0, Math.min(250, length));
  const top = size === 'small' ? 20 : 1000;
  return [Array.from({ length }, () => 1 + Math.floor(rand() * top)), rowsCount, colsCount];
}
